let ii = book.name.match(/(\d+)(?:photos|P)/)[1]
ii=Math.ceil(ii/20)
let uu=[{"name":1,"link":yy}]
for (let i = 2; i <= ii; i++)uu.push({"name":i.toString(),"link":yy+"/"+i})
